let resultados=[];async function cargarDatosBuscador(){try{const e=await fetch("/assets/data/buscador.json");resultados=e.ok?await e.json():[]}catch(e){console.error("\u274c Error al cargar buscador.json:",e)}}function filtrarResultados(e){return e=e.toLowerCase().trim(),resultados.filter(t=>t.titulo.toLowerCase().includes(e)||t.slug.toLowerCase().includes(e))}function mostrarResultadosCoincidentes(e,t){t.innerHTML=0===e.length?"<p class='sin-resultados'>Sin coincidencias.</p>":"<ul>"+e.map(e=>`<li><a href="${e.ruta}">${e.titulo}</a></li>`).join("")+"</ul>"}function initSearch(e="#searchInput",t="#searchResults"){const r=document.querySelector(e),s=document.querySelector(t);if(!r||!s)return;let a;r.addEventListener("input",()=>{clearTimeout(a),a=setTimeout(()=>{mostrarResultadosCoincidentes(filtrarResultados(r.value),s)},300)})}function initSearchUI(){const e=document.querySelector(".search-toggle"),t=document.querySelector(".search-dropdown"),r=document.querySelector(".close-search"),s=document.querySelector("#searchInput"),a=document.querySelector("#searchResults");if(!e||!t||!s)return;e.addEventListener("click",()=>{t.classList.add("activo"),s.focus()});const o=()=>{t.classList.remove("activo"),s.value="",a&&(a.innerHTML="")};r?.addEventListener("click",o),document.addEventListener("keydown",e=>{"Escape"===e.key&&o()}),document.addEventListener("click",r=>{t.contains(r.target)||e.contains(r.target)||o()})}async function initBuscador(){await cargarDatosBuscador(),initSearch(),initSearchUI()}export{initBuscador as initSearch};